import codecs,json,sys,unicodedata
assert sys.version_info[:3]==(3,14,7) and unicodedata.unidata_version=='16.0.0'
rows=[]
for name,raw in [('euc_jisx0213',b'\xae\xa1'),('shift_jisx0213',b'\x87\x9f')]:
 for split in range(5):
  for final in [False,True]:
   for position in [-1,-2,2,5]:
    seen=[]
    def handler(error):
     seen.append([error.encoding,list(error.object),error.start,error.end,error.reason])
     return ('?', position if len(seen)==1 else error.end)
    codecs.register_error('span_probe',handler)
    decoder=codecs.getincrementaldecoder(name)('span_probe')
    data=raw+raw+b'A'
    calls=[]
    for b,last in [(data[:split],False),(data[split:],final),(b'',True)]:
     try: result=['ok',list(map(ord,decoder.decode(b,last)))]
     except UnicodeError as e: result=['error',type(e).__name__,e.encoding,list(e.object),e.start,e.end,e.reason]
     except Exception as e: result=['error',type(e).__name__,str(e)]
     pending,state=decoder.getstate()
     calls.append([result,[list(pending),str(state)]])
    rows.append(dict(name=name,raw=list(raw),split=split,final=final,position=position,seen=seen,calls=calls))
print(json.dumps(rows,indent=2))
